            # Number of ways where Alice's first card is 'a', 'b', 'c'
            for card in ['a', 'b', 'c']:
                # next player
                if card == 'a':
                    new_turn = 0
                elif card == 'b':
                    new_turn = 1
                else:
                    new_turn = 2
                # Ways for Alice's top card to be this card: 3^{a-1}
                # By multiplying ways for the other players
                ways = pow(3, a - 1, MOD)
                new_a = a - 1
                new_b = b
                new_c = c
                res = (res + ways * dp(new_a, new_b, new_c, new_turn)) % MOD
        elif turn == 1:
            # Current player is Bob
            if b == 0:
                return 0
            for card in ['a', 'b', 'c']:
                if card == 'a':
                    new_turn = 0
                elif card == 'b':
                    new_turn = 1
                else:
                    new_turn = 2
                ways = pow(3, b - 1, MOD)
                new_a = a
                new_b = b - 1
                new_c = c
                res = (res + ways * dp(new_a, new_b, new_c, new_turn)) % MOD
        else:
            # Current player is Charlie
            if c == 0:
                return 0
            for card in ['a', 'b', 'c']:
                if card == 'a':
                    new_turn = 0
                elif card == 'b':
                    new_turn = 1
                else:
                    new_turn = 2
                ways = pow(3, c - 1, MOD)
                new_a = a
                new_b = b
                new_c = c - 1
                res = (res + ways * dp(new_a, new_b, new_c, new_turn)) % MOD
        return res

    # The initial state is a=N, b=M, c=K, turn=0 (Alice's turn)
    result = dp(N, M, K, 0)
